/** ReplicatedStorage.Shared.ShurikenScreenFX: on-screen combat FX through the Motion module (flash, vignette, speed lines, banners, combo, damage numbers, hit markers). Generated Luau (keep it passing tests/runtime-lint.test.ts). */
export const FX_SCREEN_MODULE_VERSION = 1;

export const FX_SCREEN_MODULE = `--!strict
-- ShurikenScreenFX v1 (generated by Shuriken Studio; safe to use, don't edit).
-- On-screen combat FX for the local player, animated through the Motion module (skill roblox-ui-motion),
-- so they follow Reduce Motion the way the game's UI does: moves and loops land at once or stay still,
-- fades still play. Client only.
--   local Screen = require(game.ReplicatedStorage.Shared.ShurikenScreenFX)
--   Screen.damage(hitPosition, 42, { crit = true })   -- a number that pops and arcs up at a world position
--   Screen.hitMarker()                                -- your hit landed: a quick tick at the crosshair
--   Screen.flash(Color3.new(1, 1, 1), 0.35)           -- a white pop on a big hit (capped; Screen.setFlashes(false))
--   Screen.lowHealth(health / maxHealth)              -- a red vignette that breathes below 35 %
--   Screen.speedLines(true)                           -- radial streaks while dashing; false to stop
--   Screen.banner("DOUBLE KILL")  Screen.combo(hits)  Screen.tint(Color3.fromRGB(80, 255, 120), 0.25, 1)
-- From the server: Effects.screen("banner", { text = "VICTORY" }, { players = { winner } }).
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Screen = {}

type Goal = { [string]: any }
type MotionApi = {
	tween: (target: Instance, info: TweenInfo, goal: Goal) -> Tween,
	reduced: () -> boolean,
	punch: (target: GuiObject, amount: number?) -> (),
	shake: (target: GuiObject, degrees: number?) -> (),
	path: (target: GuiObject, points: { UDim2 }, seconds: number, ease: ((number) -> number)?, onDone: (() -> ())?) -> () -> (),
	bezier: (x1: number, y1: number, x2: number, y2: number) -> (number) -> number,
	scope: (owner: Instance?) -> any,
	T: { [string]: TweenInfo },
}

local warned: { [string]: boolean } = {}
local function warnOnce(key: string, message: string)
	if not warned[key] then
		warned[key] = true
		warn("[ShurikenScreenFX] " .. message)
	end
end

local motionCache: MotionApi? = nil
local function motion(): MotionApi?
	if motionCache then
		return motionCache
	end
	local m = script.Parent and script.Parent:FindFirstChild("Motion")
	if m and m:IsA("ModuleScript") then
		local ok, mod = pcall(require, m)
		if ok then
			motionCache = mod :: any
			return motionCache
		end
	end
	warnOnce("motion", "needs the Motion module beside it (ReplicatedStorage.Shared.Motion; vfx_runtime adds it)")
	return nil
end

local Quad, Back, Sine = Enum.EasingStyle.Quad, Enum.EasingStyle.Back, Enum.EasingStyle.Sine

-- Type in the style of the UI showpieces (skill roblox-ui-showpieces): a display face for big words with a
-- dark outline, the UI's bold face for numbers. Screen.setFonts puts the game's own faces in.
local fonts = { display = Font.fromEnum(Enum.Font.Oswald), bold = Font.fromEnum(Enum.Font.BuilderSansBold) }

--- The game's display face (banners, combo) and bold face (damage numbers).
function Screen.setFonts(display: Font?, bold: Font?)
	fonts.display = display or fonts.display
	fonts.bold = bold or fonts.bold
end

local function outline(label: TextLabel, thickness: number): UIStroke
	local s = Instance.new("UIStroke")
	s.Color = Color3.new(0, 0, 0)
	s.Thickness = thickness
	s.Transparency = 0.2
	s.Parent = label
	return s
end
local In, Out, InOut = Enum.EasingDirection.In, Enum.EasingDirection.Out, Enum.EasingDirection.InOut

------------------------------------------------------------------------------------------- Layers
-- Two screens: "under" (DisplayOrder -1: vignette, tint, speed lines and flashes sit under the HUD so it
-- stays readable) and "over" (DisplayOrder 25: banners, combo and hit markers over the HUD, under dialogs).
local layers: { [string]: ScreenGui } = {}
local function layer(which: string): ScreenGui?
	local existing = layers[which]
	if existing and existing.Parent then
		return existing
	end
	local player = Players.LocalPlayer
	local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
	if not playerGui then
		return nil
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = "ShurikenScreenFX_" .. which
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	pcall(function()
		gui.ScreenInsets = Enum.ScreenInsets.None
	end)
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.DisplayOrder = if which == "under" then -1 else 25
	gui.Parent = playerGui
	layers[which] = gui
	return gui
end

local function fullFrame(parent: Instance, color: Color3, transparency: number): Frame
	local f = Instance.new("Frame")
	f.BorderSizePixel = 0
	f.Size = UDim2.fromScale(1, 1)
	f.BackgroundColor3 = color
	f.BackgroundTransparency = transparency
	f.Active = false
	f.Parent = parent
	return f
end

------------------------------------------------------------------------------------------- Flash and tint
local flashesOn = true
local FLASH_CAP = 0.6 -- the most a flash covers the screen (a full white frame is a seizure risk)

--- Whether full-screen flashes play (a settings toggle for players sensitive to them).
function Screen.setFlashes(on: boolean)
	flashesOn = on
end

--- A quick full-screen flash that fades: \`peak\` 0..0.6 opacity, gone in \`seconds\` (default 0.25).
function Screen.flash(color: Color3?, peak: number?, seconds: number?)
	local M = motion()
	local gui = layer("under")
	if not M or not gui or not flashesOn then
		return
	end
	local f = fullFrame(gui, color or Color3.new(1, 1, 1), 1 - math.clamp(peak or 0.35, 0, FLASH_CAP))
	local tween = M.tween(f, TweenInfo.new(seconds or 0.25, Quad, Out), { BackgroundTransparency = 1 })
	tween.Completed:Once(function()
		f:Destroy()
	end)
end

--- A colour wash that comes and goes (poison, a heal, a status): \`strength\` 0..1, held for \`seconds\`.
function Screen.tint(color: Color3, strength: number?, seconds: number?)
	local M = motion()
	local gui = layer("under")
	if not M or not gui then
		return
	end
	local f = fullFrame(gui, color, 1)
	local goal = 1 - math.clamp(strength or 0.2, 0, 0.6)
	M.tween(f, TweenInfo.new(0.15, Quad, Out), { BackgroundTransparency = goal })
	task.delay(math.max(seconds or 0.6, 0.15), function()
		local out = M.tween(f, TweenInfo.new(0.35, Quad, In), { BackgroundTransparency = 1 })
		out.Completed:Once(function()
			f:Destroy()
		end)
	end)
end

------------------------------------------------------------------------------------------- Vignette
-- Four edge bands whose gradients fade inward: a vignette that needs no texture and scales to any screen.
type Vignette = { root: Frame, bands: { Frame }, scope: any? }
local vignette: Vignette? = nil

local function makeVignette(gui: ScreenGui): Vignette
	local root = Instance.new("Frame")
	root.Name = "Vignette"
	root.BackgroundTransparency = 1
	root.Size = UDim2.fromScale(1, 1)
	root.Parent = gui
	local bands: { Frame } = {}
	-- {size, position, gradient rotation}: transparency 0 at the screen edge, 1 inward.
	type Band = { size: UDim2, position: UDim2, rotation: number }
	local specs: { Band } = {
		{ size = UDim2.fromScale(1, 0.32), position = UDim2.fromScale(0, 0), rotation = 90 },
		{ size = UDim2.fromScale(1, 0.32), position = UDim2.fromScale(0, 0.68), rotation = -90 },
		{ size = UDim2.fromScale(0.24, 1), position = UDim2.fromScale(0, 0), rotation = 0 },
		{ size = UDim2.fromScale(0.24, 1), position = UDim2.fromScale(0.76, 0), rotation = 180 },
	}
	for _, s in specs do
		local band = Instance.new("Frame")
		band.BorderSizePixel = 0
		band.BackgroundColor3 = Color3.new(0, 0, 0)
		band.BackgroundTransparency = 1
		band.Size = s.size
		band.Position = s.position
		local g = Instance.new("UIGradient")
		g.Rotation = s.rotation
		g.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(0.45, 0.55),
			NumberSequenceKeypoint.new(1, 1),
		})
		g.Parent = band
		band.Parent = root
		table.insert(bands, band)
	end
	return { root = root, bands = bands, scope = nil }
end

--- A vignette around the screen edges: strength 0 hides it, 1 is heavy. Colour default black.
function Screen.vignette(strength: number, color: Color3?, pulse: boolean?)
	local M = motion()
	local gui = layer("under")
	if not M or not gui then
		return
	end
	local v = vignette
	local vig: Vignette = if v and v.root.Parent then v else makeVignette(gui)
	vignette = vig
	if vig.scope then
		vig.scope:stop()
		vig.scope = nil
	end
	local goal = 1 - math.clamp(strength, 0, 1) * 0.85
	for _, band in vig.bands do
		band.BackgroundColor3 = color or Color3.new(0, 0, 0)
		M.tween(band, TweenInfo.new(0.35, Quad, Out), { BackgroundTransparency = goal })
	end
	if pulse and strength > 0 then
		-- A heartbeat: the bands breathe darker and back (a loop: still under Reduce Motion).
		local scope = M.scope(vig.root)
		for _, band in vig.bands do
			scope:loop(band, TweenInfo.new(0.42, Sine, InOut, -1, true, 0.35), { BackgroundTransparency = math.max(goal - 0.2, 0) })
		end
		vig.scope = scope
	end
end

--- The low-health warning: a red vignette that grows and breathes below 35 % health, gone above it.
function Screen.lowHealth(fraction: number)
	local f = math.clamp(fraction, 0, 1)
	if f >= 0.35 then
		Screen.vignette(0, Color3.fromRGB(150, 0, 0), false)
		return
	end
	Screen.vignette(0.35 + (0.35 - f) / 0.35 * 0.55, Color3.fromRGB(150, 0, 0), true)
end

------------------------------------------------------------------------------------------- Speed lines
local speed: { holder: Frame, running: boolean }? = nil
local rng = Random.new()

--- Radial streaks rushing out from the centre (dash, boost, a fall): on/off. Not shown under Reduce Motion.
function Screen.speedLines(on: boolean, color: Color3?)
	local M = motion()
	local gui = layer("under")
	if not M or not gui then
		return
	end
	local current = speed
	if not on then
		if current then
			current.running = false
			local holder = current.holder
			task.delay(0.3, function()
				holder:Destroy()
			end)
			speed = nil
		end
		return
	end
	if current or M.reduced() then
		return
	end
	local holder = Instance.new("Frame")
	holder.Name = "SpeedLines"
	holder.BackgroundTransparency = 1
	holder.Size = UDim2.fromScale(1, 1)
	holder.Parent = gui
	local state = { holder = holder, running = true }
	speed = state
	local count = 18
	for i = 1, count do
		local line = Instance.new("Frame")
		line.BorderSizePixel = 0
		line.AnchorPoint = Vector2.new(0, 0.5)
		line.BackgroundColor3 = color or Color3.new(1, 1, 1)
		line.BackgroundTransparency = 1
		line.Parent = holder
		local function launch()
			if not state.running or not line.Parent then
				line:Destroy()
				return
			end
			local angle = (i / count) * 2 * math.pi + rng:NextNumber(-0.15, 0.15)
			local dir = Vector2.new(math.cos(angle), math.sin(angle))
			local from = 0.32 + rng:NextNumber(0, 0.12)
			line.Rotation = math.deg(angle)
			line.Size = UDim2.new(rng:NextNumber(0.08, 0.16), 0, 0, rng:NextInteger(2, 3))
			line.Position = UDim2.fromScale(0.5 + dir.X * from, 0.5 + dir.Y * from * 1.6)
			line.BackgroundTransparency = 0.35
			local seconds = rng:NextNumber(0.22, 0.34)
			local tween = M.tween(line, TweenInfo.new(seconds, Quad, In), {
				Position = UDim2.fromScale(0.5 + dir.X * 0.75, 0.5 + dir.Y * 1.2),
				BackgroundTransparency = 1,
			})
			tween.Completed:Once(launch)
		end
		task.delay(rng:NextNumber(0, 0.3), launch)
	end
end

------------------------------------------------------------------------------------------- Banners and combo
export type BannerOptions = { color: Color3?, sub: string?, seconds: number?, size: number? }
local banner: TextLabel? = nil

--- A big word across the upper middle (DOUBLE KILL, VICTORY, ROUND 2): pops in, holds, fades.
function Screen.banner(text: string, opts: BannerOptions?)
	local M = motion()
	local gui = layer("over")
	if not M or not gui then
		return
	end
	local o: BannerOptions = opts or {}
	local old = banner
	if old and old.Parent then
		local leaving = old
		local edge = leaving:FindFirstChildOfClass("UIStroke")
		if edge then
			M.tween(edge, TweenInfo.new(0.12, Quad, In), { Transparency = 1 })
		end
		M.tween(leaving, TweenInfo.new(0.12, Quad, In), { TextTransparency = 1 }).Completed:Once(function()
			leaving:Destroy()
		end)
	end
	local label = Instance.new("TextLabel")
	label.Name = "Banner"
	label.AnchorPoint = Vector2.new(0.5, 0.5)
	label.Position = UDim2.fromScale(0.5, 0.28)
	label.Size = UDim2.new(0.9, 0, 0, o.size or 64)
	label.BackgroundTransparency = 1
	label.FontFace = fonts.display
	label.TextScaled = true
	label.Text = if o.sub then text .. "\\n" .. o.sub else text
	label.TextColor3 = o.color or Color3.fromRGB(255, 214, 90)
	local edge = outline(label, 3)
	local limit = Instance.new("UITextSizeConstraint")
	limit.MaxTextSize = o.size or 64
	limit.Parent = label
	local scale = Instance.new("UIScale")
	scale.Scale = if M.reduced() then 1 else 0.6
	scale.Parent = label
	label.TextTransparency = 1
	label.Parent = gui
	banner = label
	M.tween(scale, M.T.pop or TweenInfo.new(0.4, Back, Out), { Scale = 1 })
	M.tween(label, TweenInfo.new(0.12, Quad, Out), { TextTransparency = 0 })
	task.delay(o.seconds or 1.6, function()
		if not label.Parent then
			return
		end
		M.tween(edge, TweenInfo.new(0.3, Quad, In), { Transparency = 1 })
		M.tween(label, TweenInfo.new(0.3, Quad, In), { TextTransparency = 1 }).Completed:Once(function()
			label:Destroy()
		end)
	end)
end

local comboLabel: TextLabel? = nil
local comboSerial = 0

--- A hit counter at the right of the screen: punches on every hit, warms from white to red as it climbs,
--- fades after \`timeout\` seconds without a hit (default 1.8). Call it with the new count.
function Screen.combo(hits: number, timeout: number?)
	local M = motion()
	local gui = layer("over")
	if not M or not gui then
		return
	end
	local existing = comboLabel
	local l: TextLabel
	if existing and existing.Parent then
		l = existing
	else
		local made = Instance.new("TextLabel")
		made.Name = "Combo"
		made.AnchorPoint = Vector2.new(1, 0.5)
		made.Position = UDim2.new(1, -40, 0.42, 0)
		made.Size = UDim2.fromOffset(220, 72)
		made.BackgroundTransparency = 1
		made.FontFace = fonts.display
		made.TextSize = 48
		made.TextXAlignment = Enum.TextXAlignment.Right
		outline(made, 3)
		made.Parent = gui
		l = made
		comboLabel = made
	end
	l.Text = tostring(hits) .. " HITS"
	local heat = math.clamp((hits - 1) / 20, 0, 1)
	l.TextColor3 = Color3.new(1, 1, 1):Lerp(Color3.fromRGB(255, 200, 60), math.min(heat * 2, 1)):Lerp(Color3.fromRGB(255, 70, 50), math.max(heat * 2 - 1, 0))
	l.TextTransparency = 0
	local edge = l:FindFirstChildOfClass("UIStroke")
	if edge then
		edge.Transparency = 0.2
	end
	M.punch(l, 0.18)
	comboSerial += 1
	local mine = comboSerial
	task.delay(timeout or 1.8, function()
		if comboSerial == mine and l.Parent then
			M.tween(l, TweenInfo.new(0.25, Quad, In), { TextTransparency = 1 })
			if edge then
				M.tween(edge, TweenInfo.new(0.25, Quad, In), { Transparency = 1 })
			end
		end
	end)
end

------------------------------------------------------------------------------------------- Damage numbers
export type DamageOptions = { crit: boolean?, color: Color3?, heal: boolean?, text: string?, size: number? }
local liveNumbers = 0

--- A damage number at a world position: pops, arcs up and to a side, fades (crits bigger, gold, a shake;
--- heals green with a +). At most 24 at once; older ones keep going.
function Screen.damage(position: Vector3, amount: number, opts: DamageOptions?)
	local M = motion()
	if not M or not RunService:IsClient() or liveNumbers >= 24 then
		return
	end
	local o: DamageOptions = opts or {}
	local anchor = Instance.new("Attachment")
	anchor.Name = "DamageNumber"
	anchor.WorldPosition = position
	anchor.Parent = workspace.Terrain
	local board = Instance.new("BillboardGui")
	board.Size = UDim2.fromOffset(160, 140)
	board.AlwaysOnTop = true
	board.LightInfluence = 0
	board.MaxDistance = 150
	board.Adornee = anchor
	board.Parent = anchor
	local crit = o.crit == true
	local label = Instance.new("TextLabel")
	label.AnchorPoint = Vector2.new(0.5, 0.5)
	label.Size = UDim2.fromOffset(160, if crit then 46 else 34)
	label.BackgroundTransparency = 1
	label.FontFace = fonts.bold
	label.TextScaled = true
	label.Text = o.text or ((if o.heal then "+" else "") .. tostring(math.floor(amount + 0.5)) .. (if crit then "!" else ""))
	label.TextColor3 = o.color or (if o.heal then Color3.fromRGB(110, 255, 140) elseif crit then Color3.fromRGB(255, 205, 60) else Color3.new(1, 1, 1))
	label.TextStrokeColor3 = Color3.new(0, 0, 0)
	label.TextStrokeTransparency = 0.2
	label.Position = UDim2.new(0.5, 0, 1, -20)
	label.Parent = board
	local pop = Instance.new("UIScale")
	pop.Scale = if M.reduced() then 1 else 0.4
	pop.Parent = label
	liveNumbers += 1
	-- Pop in, then arc up and to a side (a Catmull-Rom path through three points), then fade.
	local side = rng:NextNumber(-1, 1)
	M.tween(pop, TweenInfo.new(0.16, Back, Out), { Scale = if crit then 1.25 else 1 })
	if crit then
		M.shake(label, 8)
	end
	local seconds = if crit then 0.95 else 0.75
	M.path(label, {
		UDim2.new(0.5, 0, 1, -20),
		UDim2.new(0.5, side * 18, 0.55, 0),
		UDim2.new(0.5, side * 30, 0.2, 0),
	}, seconds, M.bezier(0.2, 0.7, 0.4, 1))
	task.delay(seconds * 0.55, function()
		M.tween(label, TweenInfo.new(seconds * 0.45, Quad, In), { TextTransparency = 1, TextStrokeTransparency = 1 })
		M.tween(pop, TweenInfo.new(seconds * 0.45, Quad, In), { Scale = 0.7 })
	end)
	task.delay(seconds + 0.1, function()
		liveNumbers -= 1
		anchor:Destroy()
	end)
end

------------------------------------------------------------------------------------------- Hit marker
--- A quick X at the screen centre when your hit lands (shooters, ranged abilities).
function Screen.hitMarker(color: Color3?)
	local M = motion()
	local gui = layer("over")
	if not M or not gui then
		return
	end
	local holder = Instance.new("Frame")
	holder.AnchorPoint = Vector2.new(0.5, 0.5)
	holder.Position = UDim2.fromScale(0.5, 0.5)
	holder.Size = UDim2.fromOffset(28, 28)
	holder.BackgroundTransparency = 1
	holder.Rotation = 45
	holder.Parent = gui
	for _, horizontal in { true, false } do
		local bar = Instance.new("Frame")
		bar.BorderSizePixel = 0
		bar.AnchorPoint = Vector2.new(0.5, 0.5)
		bar.Position = UDim2.fromScale(0.5, 0.5)
		bar.Size = if horizontal then UDim2.new(1, 0, 0, 3) else UDim2.new(0, 3, 1, 0)
		bar.BackgroundColor3 = color or Color3.new(1, 1, 1)
		bar.Parent = holder
		M.tween(bar, TweenInfo.new(0.22, Quad, In, 0, false, 0.06), { BackgroundTransparency = 1 })
	end
	M.punch(holder, 0.35)
	task.delay(0.35, function()
		holder:Destroy()
	end)
end

--- A short screen kick (the UI's own shake, not the camera's) for UI-only games.
function Screen.shake(degrees: number?)
	local M = motion()
	local gui = layer("over")
	if M and gui then
		local holder = gui:FindFirstChildWhichIsA("GuiObject")
		if holder then
			M.shake(holder, degrees or 3)
		end
	end
end

------------------------------------------------------------------------------------------- Cues
--- Plays a cue by name with a parameter table: what effect tracks ({type = "screen", fx = ...}) and the
--- server (Effects.screen) send. fx: flash, tint, vignette, lowHealth, speedlines, banner, combo, damage,
--- hitmarker, shake.
function Screen.cue(fx: string, params: any, at: Vector3?)
	local p = if typeof(params) == "table" then params else {}
	local function color(default: Color3?): Color3?
		if typeof(p.color) == "Color3" then
			return p.color
		elseif typeof(p.color) == "string" then
			local ok, c = pcall(Color3.fromHex, p.color)
			if ok then
				return c
			end
		end
		return default
	end
	local strength = if typeof(p.strength) == "number" then p.strength else nil
	local seconds = if typeof(p.duration) == "number" then p.duration elseif typeof(p.seconds) == "number" then p.seconds else nil
	if fx == "flash" then
		Screen.flash(color(nil), strength, seconds)
	elseif fx == "tint" then
		Screen.tint(color(Color3.new(1, 1, 1)) :: Color3, strength, seconds)
	elseif fx == "vignette" then
		Screen.vignette(strength or 0.5, color(nil), p.pulse == true)
		if seconds then
			task.delay(seconds, function()
				Screen.vignette(0)
			end)
		end
	elseif fx == "lowHealth" then
		Screen.lowHealth(strength or 1)
	elseif fx == "speedlines" then
		Screen.speedLines(true, color(nil))
		task.delay(seconds or 0.4, function()
			Screen.speedLines(false)
		end)
	elseif fx == "banner" then
		Screen.banner(tostring(p.text or ""), { color = color(nil), sub = p.sub, seconds = seconds })
	elseif fx == "combo" then
		Screen.combo(if typeof(p.hits) == "number" then p.hits else 1)
	elseif fx == "damage" then
		local where = if typeof(p.position) == "Vector3" then p.position else at
		if where then
			Screen.damage(where, if typeof(p.amount) == "number" then p.amount else 0, { crit = p.crit, heal = p.heal, color = color(nil), text = p.text })
		end
	elseif fx == "hitmarker" then
		Screen.hitMarker(color(nil))
	elseif fx == "shake" then
		Screen.shake(strength)
	else
		warnOnce("cue:" .. tostring(fx), "unknown screen cue " .. tostring(fx))
	end
end

return Screen
`;
